param([ValidateSet('BASELINE','REMEDIATION')][string]$Condition='BASELINE',[switch]$Finalize)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;. (Join-Path $PSScriptRoot 'experiment-1-21-native-log-capture.ps1');$out=Join-Path $root 'backend\experiments\results\experiment-1-21\log-capture-preflight';$app='doeng-flux-exp119-fresh-first-20260803:latest';$mock='doeng-exp119-mock-frozen-20260803:latest';$project='doeng-exp121-log-probe';$files=@('backend\docker-compose.experiment.yaml','backend\docker-compose.app-instance-t3-medium.yaml','backend\docker-compose.mock-headroom-4cpu.yaml','backend\docker-compose.http-pool-400.yaml','backend\docker-compose.mock-memory-headroom.yaml','backend\docker-compose.experiment-1-12-connection-attribution.yaml','backend\docker-compose.experiment-1-19-fresh-first-lifecycle.yaml');$args=@();foreach($f in $files){$args+=@('-f',(Join-Path $root $f))};function Health($u){$end=(Get-Date).AddSeconds(90);while((Get-Date)-lt$end){try{if((Invoke-WebRequest -UseBasicParsing $u -TimeoutSec 3).StatusCode-eq200){return}}catch{};Start-Sleep 1};throw 'Health failed'};New-Item -ItemType Directory -Force -Path $out|Out-Null
if($Finalize){$b=Get-Content (Join-Path $out 'baseline.json') -Raw|ConvertFrom-Json;$r=Get-Content (Join-Path $out 'remediation.json') -Raw|ConvertFrom-Json;if($b.captureStatus-ne'APPLICATION_LOG_CAPTURE_PROBE_READY'-or$r.captureStatus-ne'APPLICATION_LOG_CAPTURE_PROBE_READY'){throw 'Probe not ready'};@{state='EXP121_READY_FOR_SIX_CORE_RUNS';warmup=0;k6=0;core=0}|ConvertTo-Json|Set-Content (Join-Path $out 'finalize.json');exit 0}
$policy=if($Condition-eq'BASELINE'){@{s='FIFO';i='0';e='0'}}else{@{s='LIFO';i='3000';e='1000'}};$env:DOENG_EXP119_APP_IMAGE=$app;$env:DOENG_EXP119_MOCK_IMAGE=$mock;$env:DOENG_EXTERNAL_LEASING_STRATEGY=$policy.s;$env:DOENG_EXTERNAL_MAX_IDLE_TIME_MS=$policy.i;$env:DOENG_EXTERNAL_EVICTION_INTERVAL_MS=$policy.e;$dir=Join-Path $out $Condition.ToLower();if(Test-Path $dir){Remove-Item $dir -Recurse -Force};New-Item -ItemType Directory -Path $dir|Out-Null
try{docker compose -p $project @args up -d --force-recreate --no-build mariadb experiment-mock flux-corrected;if($LASTEXITCODE){throw 'Compose failed'};Health 'http://127.0.0.1:9001/actuator/health';$container=(docker compose -p $project @args ps -q flux-corrected).Trim();$capture=Invoke-Exp121NativeLogCapture -RunId "PROBE-EXP121-$Condition" -ContainerId $container -ApplicationDirectory (Join-Path $dir 'application');@{condition=$Condition;policy=$policy;captureStatus='APPLICATION_LOG_CAPTURE_PROBE_READY';capture=$capture;warmup=0;k6=0;core=0}|ConvertTo-Json -Depth 8|Set-Content (Join-Path $out "$($Condition.ToLower()).json")}finally{docker compose -p $project @args down --remove-orphans|Out-Null}
